const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const money = n => new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0}).format(Math.round(n))+' TL';
const qty = n => new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}).format(n);
const analytics = (event, detail={}) => { const x=JSON.parse(localStorage.getItem('prokontAnalytics')||'[]'); x.unshift({event,detail,at:new Date().toISOString()}); localStorage.setItem('prokontAnalytics',JSON.stringify(x.slice(0,100))); };
const toast = message => { const t=$('#toast'); t.textContent=message; t.classList.add('show'); setTimeout(()=>t.classList.remove('show'),3200); };

