  boya:{name:'Boya Hesabı',category:'Duvar',poz:'15.540.1301',unit:'m²',waste:3,inputs:[['Kat sayısı','number',2],['Boya tipi','select','Silikonlu|Silikat|Elastik']],items:[['Astar','litre',.12,145,'Malzeme','10.240.2501'],['İç cephe boya','litre',.28,285,'Malzeme','15.540.1301'],['Boya işçiliği','m²',1,135,'İşçilik','15.540.1301'],['Koruma / temizlik','götürü',1,1200,'Diğer','-']]},
