  alci:{name:'Alçı & Sıva Hesabı',category:'Duvar',poz:'15.540.1601',unit:'m²',waste:7,inputs:[['Uygulama tipi','select','Saten alçı|Makine sıvası|Kaba sıva'],['Kat sayısı','number',2]],items:[['Sıva harcı','25 kg torba',.42,165,'Malzeme','10.240.2801'],['Saten alçı','25 kg torba',.20,230,'Malzeme','10.240.2802'],['Köşe profili','mtül',.32,38,'Malzeme','10.240.2803'],['Sıva / alçı işçiliği','m²',1,260,'İşçilik','15.540.1601']]},
